  // Clock and reset
  // -----------------------------------------------------------
  logic clk = 0;
  logic rst_n = 0;          // active‑low reset for convenience
  initial begin
    #5 rst_n = 1;
    #20 rst_n = 0;
    #40 rst_n = 1;
  end
  always #5 clk = ~clk;     // 100 MHz clock

  // -----------------------------------------------------------
  // Top‑level UART interface signals
  // -----------------------------------------------------------
  logic [7:0]  s_axis_tdata_val = 0;
  logic        s_axis_tvalid_val = 0;
  logic        s_axis_tready_val = 0;   // unused, keep low

  logic [7:0]  m_axis_tdata;
  logic        m_axis_tvalid;
  logic        m_axis_tready_val = 1'b1; // always ready (tie‑off)

  logic        rxd_drv;                  // driven by testbench
  logic        txd;                      // not used by testbench
  logic [15:0] prescale_val = 16'd5;     // default prescale

  // UART status outputs (unused)
  logic        tx_busy;
  logic        rx_busy;
  logic        rx_overrun_error;
  logic        rx_frame_error;

  // -----------------------------------------------------------
  // Connect DUT ports
  // -----------------------------------------------------------
  uart #(.DATA_WIDTH(8)) dut (
    .clk          (clk),
    .rst          (~rst_n),                // active‑low reset in DUT
    .s_axis_tdata (s_axis_tdata_val),
    .s_axis_tvalid(s_axis_tvalid_val),
    .s_axis_tready(s_axis_tready_val),
    .m_axis_tdata (m_axis_tdata),
    .m_axis_tvalid(m_axis_tvalid),
    .m_axis_tready(m_axis_tready_val),
    .rxd          (rxd_drv),
    .txd          (txd),
    .tx_busy      (tx_busy),
    .rx_busy      (rx_busy),
    .rx_overrun_error(rx_overrun_error),
    .rx_frame_error(rx_frame_error),
    .prescale     (prescale_val)
  );

  // -----------------------------------------------------------
  // Helper constant for bit timing (prescale = 5 → 5*8 = 40 clocks per bit)
  // -----------------------------------------------------------
  localparam int PRESCALE_VAL = 5;   // matches 16'd5

  // -----------------------------------------------------------
  // Bit‑time wait task (one bit period = PRESCALE_VAL*8 clocks)
  // -----------------------------------------------------------
  task automatic wait_one_bit;
    repeat (PRESCALE_VAL * 8) @(posedge clk);
  endtask

  // -----------------------------------------------------------
  // Frame‑send task
  //   data      – byte to transmit (LSB first)
  //   err_stop  – 1 = hold stop bit low (generates frame_error)
  // -----------------------------------------------------------
  task automatic send_frame(input byte unsigned data, input bit err_stop);
    begin
      // --- start bit (low) ---
      rxd_drv = 0;
      wait_one_bit;

      // --- 8 data bits (LSB first) ---
      for (int i = 0; i < 8; i++) begin
        rxd_drv = data[i];
        wait_one_bit;
      end

      // --- stop bit ---
      if (err_stop) begin
        rxd_drv = 0;          // hold low → frame_error while rxd is low
      end else begin
        rxd_drv = 1;          // normal high stop
      end
      wait_one_bit;

      // Return line to idle (high)
      rxd_drv = 1;
    end
  endtask

  // -----------------------------------------------------------
  // Monitor for coverage point R13_rx_resync_after_frame_error
  // -----------------------------------------------------------
